  const uploadMenuImage = async (file: File | undefined) => { if (!file) return; if (!["image/png", "image/jpeg", "image/webp"].includes(file.type)) return toast.error("الصورة يجب أن تكون PNG أو JPG أو WEBP"); if (file.size > 8 * 1024 * 1024) return toast.error("حجم الصورة يتجاوز 8 ميجابايت"); setIsUploadingMenuImage(true); try { const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => typeof reader.result === "string" ? resolve(reader.result) : reject(new Error("read")); reader.onerror = () => reject(new Error("read")); reader.readAsDataURL(file); }); const uploaded = await mediaUpload.mutateAsync({ fileName: file.name, contentType: file.type, base64, category: "menu", scope: "restaurant", restaurantId }); setNewImageUrl(uploaded.url); toast.success("تم رفع صورة الصنف إلى مكتبة المطعم"); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر رفع الصورة"); } finally { setIsUploadingMenuImage(false); } };
  const uploadCategoryImage = async (file: File | undefined) => { if (!file) return; if (!["image/png", "image/jpeg", "image/webp"].includes(file.type)) return toast.error("الصورة يجب أن تكون PNG أو JPG أو WEBP"); if (file.size > 8 * 1024 * 1024) return toast.error("حجم الصورة يتجاوز 8 ميجابايت"); setIsUploadingCategoryImage(true); try { const base64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => typeof reader.result === "string" ? resolve(reader.result) : reject(new Error("read")); reader.onerror = () => reject(new Error("read")); reader.readAsDataURL(file); }); const uploaded = await mediaUpload.mutateAsync({ fileName: file.name, contentType: file.type, base64, category: "menu", scope: "restaurant", restaurantId }); setNewCategoryImageUrl(uploaded.url); toast.success("تم رفع صورة الفئة إلى مكتبة المطعم"); } catch (error) { toast.error(error instanceof Error ? error.message : "تعذر رفع صورة الفئة"); } finally { setIsUploadingCategoryImage(false); } };
  const createMenuCategory = trpc.platform.createMenuCategory.useMutation({ onSuccess: async () => { await utils.platform.menuCategories.invalidate({ restaurantId }); setShowCategoryCreate(false); setNewCategoryName(""); setNewCategoryDescription(""); setNewCategorySortOrder("0"); setNewCategoryImageUrl(""); toast.success("تمت إضافة التصنيف"); }, onError: (error) => toast.error(`تعذر إضافة التصنيف: ${error.message}`) });
